import{_ as a,o as e,c as r,a2 as t}from"./chunks/framework.ktMMbWgA.js";const g=JSON.parse('{"title":"第 26 讲 · AI Agent — 从工具到自主智能体 · 参考","description":"","frontmatter":{"title":"第 26 讲 · AI Agent — 从工具到自主智能体 · 参考","act":5,"kind":"refs","prev":{"text":"L25 · Function Calling 与 MCP","link":"/lectures/L25-function-calling/references"},"next":{"text":"L27 · Agent 能力装配","link":"/lectures/L27-agent-skills/references"}},"headers":[],"relativePath":"lectures/L26-agent/references.md","filePath":"lectures/L26-agent/references.md","lastUpdated":null}'),l={name:"lectures/L26-agent/references.md"};function i(n,s,c,d,p,f){return e(),r("div",null,[...s[0]||(s[0]=[t('<h1 id="l26-references-ai-agent-—-从工具到自主智能体" tabindex="-1">L26 References: AI Agent — 从工具到自主智能体 <a class="header-anchor" href="#l26-references-ai-agent-—-从工具到自主智能体" aria-label="Permalink to &quot;L26 References: AI Agent — 从工具到自主智能体&quot;">​</a></h1><blockquote><p><strong>Lecture</strong>: AI Agent — 从工具到自主智能体 <strong>Course</strong>: Intelligence, Computed — From First Principles to Production AI Systems</p></blockquote><blockquote><p><strong>Last Verified</strong>: 2026-05-04 (links and citations checked; replace this when re-verifying)</p></blockquote><hr><section class="ref-card"><h2 class="ref-card-title" id="学术论文">1. 学术论文</h2><h3 class="ref-group" id="学术论文--agent-核心循环与架构">Agent 核心循环与架构</h3><ol class="ref-list"><li class="ref-item" id="ref-P1"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P1</span><a class="ref-title" href="https://arxiv.org/abs/2210.03629" target="_blank" rel="noopener">ReAct: Synergizing Reasoning and Acting in Language Models</a></div><div class="ref-meta">Yao, S., Zhao, J., Yu, D. et al. (Princeton) · 2023 · <em>ICLR 2023</em></div><p class="ref-desc"><strong>本讲主角论文。</strong> Thought-Action-Observation 交替循环的奠基工作。讲稿 [18:00–26:00] ReAct 模式的直接学术来源。paper_notes.md 闪读卡。</p></div></li><li class="ref-item" id="ref-P2"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P2</span><a class="ref-title" href="https://arxiv.org/abs/2303.11366" target="_blank" rel="noopener">Reflexion: Language Agents with Verbal Reinforcement Learning</a></div><div class="ref-meta">Shinn, N., Cassano, F., et al. · 2023 · <em>NeurIPS 2023</em></div><p class="ref-desc"><strong>Evaluator 显式化的里程碑。</strong> 反思循环 + 记忆注入。讲稿 [32:00–40:00] Reflexion 模式的核心参考。HumanEval 从 80%→91% 的数据来源。</p></div></li><li class="ref-item" id="ref-P3"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P3</span><a class="ref-title" href="https://arxiv.org/abs/2303.17651" target="_blank" rel="noopener">Self-Refine: Iterative Refinement with Self-Feedback</a></div><div class="ref-meta">Madaan, A., Tandon, N., et al. (CMU) · 2023 · <em>NeurIPS 2023</em></div><p class="ref-desc">Self-Refine = 纯 LLM 自我评估 + 自我修改（无外部反馈）。讲稿 [32:00–40:00] 与 Reflexion 的对比。</p></div></li><li class="ref-item" id="ref-P4"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P4</span><a class="ref-title" href="https://arxiv.org/abs/2303.17580" target="_blank" rel="noopener">HuggingGPT: Solving AI Tasks with ChatGPT and its Friends in Hugging Face</a></div><div class="ref-meta">Shen, Y., Song, K., et al. (Microsoft/Zhejiang) · 2023 · <em>NeurIPS 2023</em></div><p class="ref-desc"><strong>Plan-and-Execute 的经典实例。</strong> LLM 作为 controller 调度 Hugging Face 模型。讲稿 [26:00–32:00] 的实例参考。</p></div></li><li class="ref-item" id="ref-P5"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P5</span><a class="ref-title" href="https://github.com/Significant-Gravitas/AutoGPT" target="_blank" rel="noopener">Auto-GPT: An Autonomous GPT-4 Experiment</a></div><div class="ref-meta">Richards, T. (Significant Gravitas) · 2023 · GitHub repo</div><p class="ref-desc"><strong>Agent 热潮的引爆点。</strong> 虽非论文，但其&quot;自主 Agent&quot;概念影响了整个领域。讲稿开场的文化参考。</p></div></li><li class="ref-item" id="ref-P6"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P6</span><a class="ref-title" href="https://arxiv.org/abs/2305.04091" target="_blank" rel="noopener">Plan-and-Solve Prompting: Improving Zero-Shot Chain-of-Thought Reasoning</a></div><div class="ref-meta">Wang, L., Xu, W., et al. · 2023 · <em>ACL 2023</em></div><p class="ref-desc">Plan-and-Solve 的学术基础。先生成计划再逐步执行。讲稿 [26:00–32:00] Plan-and-Execute 的学术参考。</p></div></li><li class="ref-item" id="ref-P7"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P7</span><a class="ref-title" href="https://arxiv.org/abs/2304.03442" target="_blank" rel="noopener">Generative Agents: Interactive Simulacra of Human Behavior</a></div><div class="ref-meta">Park, J.S., O&#39;Brien, J.C., et al. (Stanford) · 2023 · <em>UIST 2023</em></div><p class="ref-desc"><strong>记忆系统设计的标杆。</strong> 反射（Reflection）+ 记忆检索 + 规划。讲稿 [48:00–56:00] 记忆系统的学术参考。</p></div></li><li class="ref-item" id="ref-P8"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P8</span><a class="ref-title" href="https://arxiv.org/abs/2302.04761" target="_blank" rel="noopener">Toolformer: Language Models Can Teach Themselves to Use Tools</a></div><div class="ref-meta">Schick, T. et al. (Meta AI) · 2023 · <em>NeurIPS 2023</em></div><p class="ref-desc">L31 已引用。Agent 工具使用的奠基论文——LLM 自学何时用工具。</p></div></li><li class="ref-item" id="ref-P9"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P9</span><a class="ref-title" href="https://arxiv.org/abs/2310.04406" target="_blank" rel="noopener">Language Agent Tree Search Unifies Reasoning Acting and Planning in Language Models</a></div><div class="ref-meta">Zhou, A. et al. (UIUC) · 2024 · <em>ICML 2024</em></div><p class="ref-desc">树搜索 + Agent 循环的融合。Evaluator 用于节点评估。PGE 中 Evaluator 的高级变体。</p></div></li><li class="ref-item" id="ref-P10"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P10</span><a class="ref-title" href="https://arxiv.org/abs/2309.02427" target="_blank" rel="noopener">Cognitive Architectures for Language Agents (CoALA)</a></div><div class="ref-meta">Sumers, T., Yao, S., et al. (Princeton) · 2024 · <em>arxiv preprint</em></div><p class="ref-desc"><strong>Agent 认知架构的综述。</strong> 记忆/推理/行动/学习四模块。讲稿 [06:00–18:00] PGE 框架的学术基础之一。</p></div></li></ol><h3 class="ref-group" id="学术论文--agent-评估与失效模式">Agent 评估与失效模式</h3><ol class="ref-list"><li class="ref-item" id="ref-P11"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P11</span><a class="ref-title" href="https://arxiv.org/abs/2308.03688" target="_blank" rel="noopener">AgentBench: Evaluating LLMs as Agents</a></div><div class="ref-meta">Liu, X. et al. (Tsinghua) · 2023 · <em>ICLR 2024</em></div><p class="ref-desc">Agent 能力 benchmark。讲稿 [72:00–84:00] 失败模式分析的数据来源。</p></div></li><li class="ref-item" id="ref-P12"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P12</span><a class="ref-title" href="https://arxiv.org/abs/2310.06770" target="_blank" rel="noopener">SWE-bench: Can Language Models Resolve Real-World GitHub Issues?</a></div><div class="ref-meta">Jimenez, C.E. et al. (Princeton) · 2024 · <em>ICLR 2024</em></div><p class="ref-desc">Agent 在真实软件工程任务上的 benchmark。Agent 失败模式的实证数据。</p></div></li><li class="ref-item" id="ref-P13"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P13</span><a class="ref-title" href="https://arxiv.org/abs/2311.12983" target="_blank" rel="noopener">GAIA: A Benchmark for General AI Assistants</a></div><div class="ref-meta">Mialon, G. et al. (Meta/HuggingFace) · 2024 · <em>ICLR 2024</em></div><p class="ref-desc"><strong>通用 Agent 事实上的总 benchmark。</strong> 需要多步推理 + 工具使用的 466 个人类友好问题。</p></div></li><li class="ref-item" id="ref-P14"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P14</span><a class="ref-title" href="https://arxiv.org/abs/2406.12045" target="_blank" rel="noopener">τ-bench: A Benchmark for Tool-Agent-User Interaction in Real-World Domains</a></div><div class="ref-meta">Yao, S. et al. (Sierra) · 2024 · <em>arxiv preprint</em></div><p class="ref-desc">陆业 Agent benchmark——隐式用户意图、多轮交互、实际商业领域。</p></div></li><li class="ref-item" id="ref-P15"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P15</span><a class="ref-title" href="https://arxiv.org/abs/2407.03502" target="_blank" rel="noopener">AgentInstruct: Toward Generative Teaching with Agentic Flows</a></div><div class="ref-meta">Mitra, A. et al. (Microsoft) · 2024 · <em>arxiv preprint</em></div><p class="ref-desc">Agent flows 合成训练数据——「Agent 训练 LLM」的反向思路。</p></div></li><li class="ref-item" id="ref-P16"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P16</span><a class="ref-title" href="https://cognition.ai/blog/dont-build-multi-agents" target="_blank" rel="noopener">Don&#39;t Build Multi-Agents (Cognition)</a></div><div class="ref-meta">Walden Yan et al. (Cognition AI) · 2025 · <em>Engineering blog</em></div><p class="ref-desc"><strong>反直觉论文。</strong> Devin 团队论证：多个 Agent 的上下文隐式冲突使 Multi-Agent 不如单 Agent 有效。</p></div></li><li class="ref-item" id="ref-P17"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P17</span><a class="ref-title" href="https://arxiv.org/abs/2402.19427" target="_blank" rel="noopener">Theoretical Foundations of Deep Selective State-Space Models</a></div><div class="ref-meta">Saroyan, M. et al. · 2024 · <em>arxiv preprint</em></div><p class="ref-desc">Agent 状态空间推理的理论基础——为「什么是 Agent 总论起点」提供数学视角。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="行业报告与博文">2. 行业报告与博文</h2><ol class="ref-list"><li class="ref-item" id="ref-A1"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A1</span><a class="ref-title" href="https://www.anthropic.com/research/building-effective-agents" target="_blank" rel="noopener">Building Effective Agents</a></div><div class="ref-meta">Anthropic</div><p class="ref-desc"><strong>全讲最重要的工程参考。</strong> Agent 设计模式（workflows vs agents）、工具设计、错误处理。&quot;能用单 Agent 就不用 Multi-Agent&quot;。</p></div></li><li class="ref-item" id="ref-A2"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A2</span><a class="ref-title" href="https://cdn.openai.com/business-guides-and-resources/a-practical-guide-to-building-agents.pdf" target="_blank" rel="noopener">A Practical Guide to Building Agents</a></div><div class="ref-meta">OpenAI</div><p class="ref-desc">OpenAI 官方 Agent 构建指南。Agent 架构模式、Guardrails、失败处理。</p></div></li><li class="ref-item" id="ref-A3"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A3</span><a class="ref-title" href="https://bair.berkeley.edu/blog/2024/02/18/compound-ai-systems/" target="_blank" rel="noopener">The Shift from Models to Compound AI Systems</a></div><div class="ref-meta">Zaharia, M. et al. (Berkeley)</div><p class="ref-desc">&quot;复合 AI 系统&quot;视角——Agent 是最复杂的复合系统。讲稿 [06:00–10:00] 统一框架的思想来源之一。</p></div></li><li class="ref-item" id="ref-A4"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A4</span><a class="ref-title" href="https://lilianweng.github.io/posts/2023-06-23-agent/" target="_blank" rel="noopener">LLM Powered Autonomous Agents</a></div><div class="ref-meta">Lilian Weng (OpenAI)</div><p class="ref-desc"><strong>Agent 综述博客的标杆。</strong> 规划 / 记忆 / 工具使用三大模块。讲稿全局的参考框架。</p></div></li><li class="ref-item" id="ref-A5"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A5</span><a class="ref-title" href="https://huyenchip.com/2025/01/07/agents.html" target="_blank" rel="noopener">What are AI Agents?</a></div><div class="ref-meta">Chip Huyen</div><p class="ref-desc">Agent 的定义、分类、评估。工程视角。讲稿 [72:00–84:00] 失败模式的参考。</p></div></li><li class="ref-item" id="ref-A6"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A6</span><span class="ref-title">AI Agent 基础设施的统一理解</span></div><div class="ref-meta">Various (中文社区)</div><p class="ref-desc">中文视角的 Agent 综述。适合中文学员扩展阅读。</p></div></li><li class="ref-item" id="ref-A7"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A7</span><a class="ref-title" href="https://blog.jetbrains.com/ai/" target="_blank" rel="noopener">How We Built JetBrains&#39; AI Assistant Agent</a></div><div class="ref-meta">JetBrains AI</div><p class="ref-desc">生产级 Agent 的架构总结——IDE 场景下怎么设计记忆与错误恢复。</p></div></li><li class="ref-item" id="ref-A8"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A8</span><a class="ref-title" href="https://eugeneyan.com/writing/" target="_blank" rel="noopener">The Bitter Lesson of Agents</a></div><div class="ref-meta">Eugene Yan</div><p class="ref-desc">2025 年 Eugene Yan 总结：<strong>「模型越强，需要的架构越简单」</strong>——讲稿「Building Effective Agents」的补充。</p></div></li><li class="ref-item" id="ref-A9"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A9</span><a class="ref-title" href="https://manus.im/blog" target="_blank" rel="noopener">Manus AI · Building a General-Purpose Agent</a></div><div class="ref-meta">Manus AI</div><p class="ref-desc">Manus 团队公开一年产品迭代中的 Agent 架构、记忆、评估与上下文工程总结。</p></div></li><li class="ref-item" id="ref-A10"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A10</span><a class="ref-title" href="https://openai.com/index/computer-using-agent/" target="_blank" rel="noopener">OpenAI · Computer-Using Agent (CUA)</a></div><div class="ref-meta">OpenAI Research</div><p class="ref-desc">OpenAI 2025 年发布 Operator 的技术报告——基于屏幕 + 鼠标键盘的 Agent 设计。</p></div></li><li class="ref-item" id="ref-A11"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A11</span><a class="ref-title" href="https://www.anthropic.com/news/3-5-models-and-computer-use" target="_blank" rel="noopener">Anthropic · Computer Use</a></div><div class="ref-meta">Anthropic</div><p class="ref-desc">Claude Computer Use 发布公告——Agent 控制计算机的能力边界与路线。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="书籍">3. 书籍</h2><ol class="ref-list"><li class="ref-item" id="ref-B1"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B1</span><span class="ref-title"><strong>AI Engineering</strong> (Ch. 5-6: Agents &amp; Tool Use)</span></div><div class="ref-meta">Chip Huyen · 2025 · O&#39;Reilly</div><p class="ref-desc">Agent 架构、记忆、工具调用的工程视角。L19 已引用，本讲继续作为核心工程参考。</p></div></li><li class="ref-item" id="ref-B2"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B2</span><span class="ref-title"><strong>Building LLM Powered Applications</strong> (Ch. 9-10: Agents)</span></div><div class="ref-meta">Valentina Alto · 2024 · Packt</div><p class="ref-desc">Agent 设计模式和框架实战。LangChain Agent 章节与本讲框架横评互补。</p></div></li><li class="ref-item" id="ref-B3"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B3</span><span class="ref-title">Multi-Agent Systems: Algorithmic, Game-Theoretic, and Logical Foundations</span></div><div class="ref-meta">Shoham &amp; Leyton-Brown · 2009 · Cambridge</div><p class="ref-desc">Multi-Agent 理论基础。学术深度参考——想深入 Multi-Agent 理论的学员可读。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="官方框架文档">4. 官方框架文档</h2><ol class="ref-list"><li class="ref-item" id="ref-D1"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">D1</span><a class="ref-title" href="https://langchain-ai.github.io/langgraph/" target="_blank" rel="noopener">LangGraph Documentation</a></div><div class="ref-meta">LangChain AI</div><p class="ref-desc">LangGraph 状态机 Agent 框架。讲稿 [58:00–72:00] 框架横评的核心参考。</p></div></li><li class="ref-item" id="ref-D2"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">D2</span><a class="ref-title" href="https://docs.crewai.com/" target="_blank" rel="noopener">CrewAI Documentation</a></div><div class="ref-meta">CrewAI</div><p class="ref-desc">Multi-Agent 协作框架。讲稿 [58:00–72:00] 框架横评的核心参考。</p></div></li><li class="ref-item" id="ref-D3"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">D3</span><a class="ref-title" href="https://microsoft.github.io/autogen/" target="_blank" rel="noopener">AutoGen Documentation</a></div><div class="ref-meta">Microsoft</div><p class="ref-desc">多 Agent 对话框架。讲稿 [58:00–72:00] 框架横评的核心参考。</p></div></li><li class="ref-item" id="ref-D4"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">D4</span><a class="ref-title" href="https://mastra.ai/docs" target="_blank" rel="noopener">Mastra Documentation</a></div><div class="ref-meta">Mastra</div><p class="ref-desc">TypeScript-first AI 工程框架。讲稿 [58:00–72:00] 框架横评参考。</p></div></li><li class="ref-item" id="ref-D5"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">D5</span><a class="ref-title" href="https://docs.anthropic.com/en/docs/agents-and-tools" target="_blank" rel="noopener">Claude Agent SDK</a></div><div class="ref-meta">Anthropic</div><p class="ref-desc">Anthropic 官方 Agent SDK。极简设计哲学。讲稿 [58:00–72:00] 框架横评核心参考。</p></div></li><li class="ref-item" id="ref-D6"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">D6</span><a class="ref-title" href="https://github.com/openai/openai-agents-python" target="_blank" rel="noopener">OpenAI Agents SDK</a></div><div class="ref-meta">OpenAI</div><p class="ref-desc">OpenAI 官方 Agent 框架（从 Swarm 演进）。内置 Guardrails。讲稿框架横评参考。</p></div></li><li class="ref-item" id="ref-D7"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">D7</span><a class="ref-title" href="https://github.com/google/adk-python" target="_blank" rel="noopener">Google ADK</a></div><div class="ref-meta">Google</div><p class="ref-desc">Google 官方 Agent Development Kit。Gemini 原生集成。讲稿框架横评参考。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="代码仓库">5. 代码仓库</h2><ol class="ref-list"><li class="ref-item" id="ref-C1"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C1</span><a class="ref-title" href="https://github.com/langchain-ai/langgraph" target="_blank" rel="noopener">LangGraph</a></div><div class="ref-meta">LangChain AI</div><p class="ref-desc">通用状态机 Agent 框架。本讲最重要的框架代码仓库之一。</p></div></li><li class="ref-item" id="ref-C2"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C2</span><a class="ref-title" href="https://github.com/crewAIInc/crewAI" target="_blank" rel="noopener">CrewAI</a></div><div class="ref-meta">CrewAI</div><p class="ref-desc">Multi-Agent 协作框架源码。</p></div></li><li class="ref-item" id="ref-C3"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C3</span><a class="ref-title" href="https://github.com/microsoft/autogen" target="_blank" rel="noopener">AutoGen</a></div><div class="ref-meta">Microsoft</div><p class="ref-desc">多 Agent 对话框架源码。</p></div></li><li class="ref-item" id="ref-C4"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C4</span><a class="ref-title" href="https://github.com/mastra-ai/mastra" target="_blank" rel="noopener">Mastra</a></div><div class="ref-meta">Mastra</div><p class="ref-desc">TypeScript-first AI 框架源码。</p></div></li><li class="ref-item" id="ref-C5"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C5</span><a class="ref-title" href="https://github.com/openai/openai-agents-python" target="_blank" rel="noopener">OpenAI Agents SDK (Python)</a></div><div class="ref-meta">OpenAI</div><p class="ref-desc">OpenAI 官方 Agent SDK 源码。</p></div></li><li class="ref-item" id="ref-C6"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C6</span><a class="ref-title" href="https://github.com/google/adk-python" target="_blank" rel="noopener">Google ADK (Python)</a></div><div class="ref-meta">Google</div><p class="ref-desc">Google Agent Development Kit 源码。</p></div></li><li class="ref-item" id="ref-C7"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C7</span><a class="ref-title" href="https://github.com/Significant-Gravitas/AutoGPT" target="_blank" rel="noopener">AutoGPT</a></div><div class="ref-meta">Significant Gravitas</div><p class="ref-desc">2023 年 Agent 热潮的引爆项目。历史参考。</p></div></li><li class="ref-item" id="ref-C8"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C8</span><a class="ref-title" href="https://github.com/yoheinakajima/babyagi" target="_blank" rel="noopener">BabyAGI</a></div><div class="ref-meta">Yohei Nakajima</div><p class="ref-desc">极简 Agent 实现（~100 行）。概念验证——适合理解 Agent 核心循环。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="视频">6. 视频</h2><ol class="ref-list"><li class="ref-item" id="ref-V1"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V1</span><a class="ref-title" href="https://www.youtube.com/@Fireship" target="_blank" rel="noopener">What are AI Agents? (Full Breakdown)</a></div><div class="ref-meta">Fireship · ~10 min</div><p class="ref-desc">Agent 概念快速入门。观众课后复习推荐。</p></div></li><li class="ref-item" id="ref-V2"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V2</span><a class="ref-title" href="https://www.youtube.com/@jamesbriggs" target="_blank" rel="noopener">AI Agents Explained — From ReAct to Multi-Agent Systems</a></div><div class="ref-meta">James Briggs · ~30 min</div><p class="ref-desc">ReAct → Plan-and-Execute → Multi-Agent 的完整讲解。与本讲线索高度一致。</p></div></li><li class="ref-item" id="ref-V3"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V3</span><a class="ref-title" href="https://www.youtube.com/@LangChain" target="_blank" rel="noopener">Building AI Agents with LangGraph</a></div><div class="ref-meta">LangChain / Various · ~40 min</div><p class="ref-desc">LangGraph 实战教程。框架横评段的补充材料。</p></div></li><li class="ref-item" id="ref-V4"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V4</span><a class="ref-title" href="https://www.youtube.com/@OpenAI" target="_blank" rel="noopener">How to Build an AI Agent (OpenAI)</a></div><div class="ref-meta">OpenAI DevDay / Various · ~20 min</div><p class="ref-desc">OpenAI 官方 Agent 构建指南。Agents SDK 实操。</p></div></li><li class="ref-item" id="ref-V5"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V5</span><a class="ref-title" href="https://www.youtube.com/" target="_blank" rel="noopener">Agents (Full Lecture) — Stanford CS229</a></div><div class="ref-meta">Andrew Ng / Various · ~60 min</div><p class="ref-desc">学术视角的 Agent 讲解。适合想要更多理论深度的学员。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="互动工具-playgrounds">7. 互动工具 &amp; Playgrounds</h2><ol class="ref-list"><li class="ref-item" id="ref-T1"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">T1</span><a class="ref-title" href="https://smith.langchain.com/" target="_blank" rel="noopener"></a></div><p class="ref-desc">Agent 执行追踪和调试。可视化每步 Thought/Action/Observation。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">Tool：</span><strong>LangSmith (LangChain)</strong></p></div></li><li class="ref-item" id="ref-T2"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">T2</span><a class="ref-title" href="https://www.agentops.ai/" target="_blank" rel="noopener"></a></div><p class="ref-desc">Agent 运行监控。成本追踪、性能分析。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">Tool：</span><strong>Agentops</strong></p></div></li><li class="ref-item" id="ref-T3"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">T3</span><a class="ref-title" href="https://platform.openai.com/playground" target="_blank" rel="noopener"></a></div><p class="ref-desc">在线体验 Agent 模式。快速原型验证。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">Tool：</span><strong>OpenAI Playground (Agent)</strong></p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="阅读路线推荐">阅读路线推荐</h2><h3 class="ref-group" id="阅读路线推荐--最小必读-30-分钟">🟢 最小必读（30 分钟）</h3><p class="ref-prose">1. <strong>A1</strong> Anthropic <em>Building Effective Agents</em>（15 min）</p><p class="ref-prose">2. <strong>A4</strong> Lilian Weng <em>LLM Powered Autonomous Agents</em>（15 min）</p><h3 class="ref-group" id="阅读路线推荐--推荐阅读-2-小时">🟡 推荐阅读（+2 小时）</h3><p class="ref-prose">3. <strong>P1</strong> ReAct 论文（30 min — 配合 paper_notes.md）</p><p class="ref-prose">4. <strong>P2</strong> Reflexion 论文 §3-4（30 min）</p><p class="ref-prose">5. <strong>A2</strong> OpenAI <em>Practical Guide to Building Agents</em>（20 min）</p><p class="ref-prose">6. <strong>A5</strong> Chip Huyen <em>What are AI Agents?</em>（20 min）</p><p class="ref-prose">7. <strong>P10</strong> CoALA: Cognitive Architectures for Language Agents（20 min）</p><h3 class="ref-group" id="阅读路线推荐--深度研究-4-小时">🔴 深度研究（+4 小时）</h3><p class="ref-prose">8. <strong>P3</strong> Self-Refine 论文</p><p class="ref-prose">9. <strong>P4</strong> HuggingGPT 论文</p><p class="ref-prose">10. <strong>P7</strong> Generative Agents 论文（记忆系统的标杆）</p><p class="ref-prose">11. <strong>P9</strong> Language Agent Tree Search</p><p class="ref-prose">12. <strong>B1</strong> Chip Huyen <em>AI Engineering</em> Ch. 5-6</p><p class="ref-prose">13. 选一个框架的文档通读：D1(LangGraph) 或 D5(Claude Agent SDK)</p></section>',12)])])}const v=a(l,[["render",i]]);export{g as __pageData,v as default};
